#!/usr/bin/env python3
"""Dependency-free Neural Mech asset registry."""
from html import escape
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlparse

HOST, PORT = "127.0.0.1", 8000

CSS = '''
:root{--paper:#f2f0e9;--ink:#171916;--muted:#656960;--steel:#a8aca4;--line:#c8c9c1;--orange:#ef5b2a;--green:#287650;--white:#faf9f5;--display:"Arial Narrow","Roboto Condensed","Helvetica Neue",sans-serif;font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;color-scheme:light}*{box-sizing:border-box}body{margin:0;color:var(--ink);background-color:var(--paper);background-image:linear-gradient(#17191609 1px,transparent 1px),linear-gradient(90deg,#17191609 1px,transparent 1px);background-size:32px 32px;min-height:100vh}a{color:inherit}.shell{width:min(1180px,calc(100% - 48px));margin:auto}.topbar{border-bottom:1px solid var(--steel);background:#f2f0e9f5}.nav{height:72px;display:flex;align-items:center}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;font-family:var(--display);font-weight:900;text-transform:uppercase;letter-spacing:.08em}.mark{width:28px;color:var(--orange)}.context{margin-left:24px;padding-left:24px;border-left:1px solid var(--steel);color:var(--muted);font-size:11px;letter-spacing:.14em;text-transform:uppercase}.system{margin-left:auto;display:flex;align-items:center;gap:9px;font:800 10px/1 var(--display);letter-spacing:.14em;text-transform:uppercase}.pulse{width:8px;height:8px;background:var(--green);border-radius:50%;box-shadow:0 0 0 4px #2876501f}main{min-height:calc(100vh - 137px)}.hero{padding:88px 0 58px;border-bottom:1px solid var(--steel);display:grid;grid-template-columns:1fr 280px;gap:48px;align-items:end}.eyebrow{margin:0 0 16px;color:var(--orange);font:800 11px/1 var(--display);letter-spacing:.2em;text-transform:uppercase}.hero h1,.detail-title{margin:0;font:900 clamp(64px,10vw,132px)/.77 var(--display);letter-spacing:-.055em;text-transform:uppercase}.hero-copy p{margin:0 0 28px;color:#454940;font-size:16px;line-height:1.55}.count{border-top:2px solid var(--ink);padding-top:12px;display:flex;justify-content:space-between;font:700 11px/1 var(--display);letter-spacing:.13em;text-transform:uppercase}.count strong{font-size:25px;letter-spacing:0}.registry{padding:34px 0 72px}.registry-head{display:flex;justify-content:space-between;margin-bottom:14px;font:700 10px/1 var(--display);letter-spacing:.17em;text-transform:uppercase;color:var(--muted)}.asset{position:relative;display:grid;grid-template-columns:1.15fr .85fr;text-decoration:none;border:1px solid var(--ink);background:var(--white);min-height:330px;overflow:hidden;transition:.25s}.asset:before{content:"";position:absolute;inset:0 auto 0 0;width:7px;background:var(--orange)}.asset:hover{transform:translateY(-4px);box-shadow:10px 10px 0 var(--ink)}.asset:focus-visible,.back:focus-visible,.brand:focus-visible{outline:3px solid var(--orange);outline-offset:4px}.asset-info{padding:36px 38px 34px 44px;display:flex;flex-direction:column}.asset-kicker,.micro{font:800 10px/1 var(--display);letter-spacing:.17em;text-transform:uppercase;color:var(--muted)}.asset h2{margin:18px 0 5px;font:900 clamp(42px,6vw,76px)/.9 var(--display);letter-spacing:-.035em}.asset-type{font:15px var(--display);text-transform:uppercase;letter-spacing:.06em}.facts{margin-top:auto;display:grid;grid-template-columns:1fr 1fr;gap:24px;border-top:1px solid var(--line);padding-top:20px}.fact span{display:block;color:var(--muted);font:700 9px/1 var(--display);letter-spacing:.15em;text-transform:uppercase;margin-bottom:8px}.fact strong{font-size:13px}.status{color:var(--green);display:flex;align-items:center;gap:7px}.status:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.asset-visual{display:grid;place-items:center;background:#dfe1da;border-left:1px solid var(--ink);color:#353a34;padding:24px;position:relative}.asset-visual:after{content:"OPEN TWIN  ↗";position:absolute;right:20px;bottom:18px;background:var(--orange);color:white;padding:9px 11px;font:800 10px/1 var(--display);letter-spacing:.13em}.schematic{width:100%;height:auto}.fan{transform-box:fill-box;transform-origin:center}.air{stroke-dasharray:10 7;animation:flow 1.25s linear infinite}.air-out{animation-direction:reverse}.site-footer{border-top:1px solid var(--steel);padding:22px 0;color:var(--muted);font-size:11px;letter-spacing:.08em;text-transform:uppercase}.site-footer .shell{display:flex;justify-content:space-between}.back{display:inline-flex;text-decoration:none;font:800 11px/1 var(--display);letter-spacing:.13em;text-transform:uppercase;margin:46px 0 56px}.back:hover{color:var(--orange)}.detail-head{display:flex;justify-content:space-between;gap:40px;align-items:end;margin-bottom:38px}.detail-title{font-size:clamp(54px,9vw,116px)}.detail-heading{margin:0;max-width:270px;font:800 17px/1.15 var(--display);letter-spacing:.04em;text-transform:uppercase}.detail-heading span{display:block;color:var(--orange);font-size:11px;letter-spacing:.16em;margin-bottom:10px}.twin-layout{display:grid;grid-template-columns:1.65fr .55fr;border:1px solid var(--ink);background:var(--white);margin-bottom:72px}.twin-stage{min-height:470px;padding:35px;background:#dfe1da;display:grid;place-items:center;border-right:1px solid var(--ink);position:relative}.twin-stage:before{content:"AIRFLOW SCHEMATIC / NOT LIVE";position:absolute;top:20px;left:22px;font:700 9px/1 var(--display);letter-spacing:.15em}.meta{padding:28px 26px;display:flex;flex-direction:column}.meta h2{font:900 18px/1 var(--display);text-transform:uppercase;margin:0 0 25px}.meta dl{margin:0}.meta dl div{display:flex;justify-content:space-between;gap:12px;border-top:1px solid var(--line);padding:14px 0}.meta dt{color:var(--muted);font:700 9px/1 var(--display);letter-spacing:.13em;text-transform:uppercase}.meta dd{margin:0;text-align:right;font-size:12px;font-weight:700}.telemetry{margin-top:auto;padding-top:32px}.telemetry-row{height:36px;border-top:1px dashed var(--steel);display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:10px}.telemetry-row i{width:70px;height:5px;background:repeating-linear-gradient(90deg,var(--steel) 0 5px,transparent 5px 9px)}.notfound{padding:100px 0}.notfound h1{font:900 70px/1 var(--display);text-transform:uppercase;margin:0 0 20px}@keyframes flow{to{stroke-dashoffset:-34}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media(max-width:760px){.shell{width:calc(100% - 30px)}.nav{height:62px}.context{display:none}.system{font-size:9px}.hero{padding:62px 0 38px;grid-template-columns:1fr;gap:36px}.asset{grid-template-columns:1fr}.asset-info{padding:30px 25px 28px 31px;min-height:275px}.asset-visual{border-left:0;border-top:1px solid var(--ink);min-height:220px}.detail-head{display:block}.detail-heading{margin-top:28px}.back{margin:35px 0 44px}.twin-layout{grid-template-columns:1fr}.twin-stage{min-height:280px;padding:18px;border-right:0;border-bottom:1px solid var(--ink)}.meta{min-height:380px}.site-footer .shell{display:block;line-height:1.8}}

/* Defensive narrow-screen layout: every grid child may shrink and wrap. */
html,body{max-width:100%;overflow-x:hidden}.shell,.hero>*,.asset>*,.twin-layout>*,.nav>*{min-width:0}.mark{flex:0 0 28px}.hero{grid-template-columns:minmax(0,1fr) 280px}.hero h1,.detail-title,.hero-copy p{overflow-wrap:anywhere}.schematic{display:block;max-width:100%}
@media(max-width:760px){
  .shell{width:auto;margin-left:15px;margin-right:15px}.brand{font-size:14px}.system{font-size:0;white-space:nowrap}.system:after{content:"LIVE";font:800 9px/1 var(--display);letter-spacing:.14em}.pulse{flex:0 0 8px}
  .hero{grid-template-columns:minmax(0,1fr)}
  .asset{grid-template-columns:minmax(0,1fr);max-width:100%}.facts{grid-template-columns:minmax(0,1fr);gap:16px}
  .asset-visual{width:100%;padding:18px 12px 54px;overflow:hidden}.asset-visual:after{left:12px;right:auto;bottom:12px;max-width:calc(100% - 24px);white-space:nowrap}
  .detail-title{font-size:clamp(44px,18vw,72px);line-height:.86}.detail-head{min-width:0}
  .twin-layout{grid-template-columns:minmax(0,1fr);max-width:100%}.twin-stage{width:100%;min-height:250px;padding:42px 8px 14px;overflow:hidden}
  .meta{min-height:0;padding:28px 22px}.meta dl div{display:block}.meta dt{display:block;margin-bottom:8px}.meta dd{text-align:left;overflow-wrap:anywhere;max-width:100%}.telemetry{margin-top:30px}
  .site-footer .shell{display:flex;flex-direction:column;align-items:flex-start;gap:9px;line-height:1.4}.site-footer .shell span{display:block;max-width:100%;overflow-wrap:anywhere}
}
'''

def mark():
    return '<svg class="mark" viewBox="0 0 30 30" aria-hidden="true"><path d="M2 24V6h6l7 10 7-10h6v18h-6V15l-7 10L8 15v9zM2 2h26v2H2z" fill="currentColor"/></svg>'

def hvac(detail=False):
    return f'''<svg class="schematic{' schematic-detail' if detail else ''}" viewBox="0 0 720 300" role="img" aria-label="HVAC air handling unit and airflow diagram"><defs><pattern id="dots" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="currentColor" opacity=".17"/></pattern></defs><rect width="720" height="300" fill="url(#dots)"/><g class="air" fill="none" stroke="currentColor" stroke-width="2"><path d="M34 118h100M34 150h90M34 182h100"/><path d="m124 112 12 6-12 6m0 20 12 6-12 6m0 20 12 6-12 6"/></g><g fill="none" stroke="currentColor" stroke-width="3"><path d="M150 78h390v144H150zM265 78v144M420 78v144M540 112h145v76H540"/></g><g class="fan" transform="translate(343 150)" fill="currentColor"><circle r="48" fill="none" stroke="currentColor" stroke-width="3"/><circle r="8"/><path d="M3-10C12-42 33-38 38-31 7-5 12 3 3 10C-5 5-5-3 3-10Z"/><path d="M3-10C12-42 33-38 38-31 7-5 12 3 3 10C-5 5-5-3 3-10Z" transform="rotate(120)"/><path d="M3-10C12-42 33-38 38-31 7-5 12 3 3 10C-5 5-5-3 3-10Z" transform="rotate(240)"/></g><g stroke="currentColor" stroke-width="3" fill="none"><path d="m173 101 68 20-68 20 68 20-68 20 68 20m203-99 50 18-50 18 50 18-50 18 50 18"/></g><g class="air air-out" fill="none" stroke="currentColor" stroke-width="2"><path d="M575 126h92M575 150h102M575 174h92"/><path d="m657 120 12 6-12 6m10 12 12 6-12 6m-10 12 12 6-12 6"/></g><g fill="currentColor" font-family="Arial" font-size="10" letter-spacing="1.4"><text x="151" y="64">INTAKE</text><text x="305" y="64">EC FAN</text><text x="420" y="64">COIL</text><text x="576" y="105">SUPPLY</text></g></svg>'''

def nav():
    return f'<header class="topbar"><nav class="nav shell"><a class="brand" href="/assets">{mark()}<span>Neural Mech</span></a><span class="context">Asset registry</span><span class="system"><i class="pulse"></i> System nominal</span></nav></header>'

def page(title, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f2f0e9"><title>{escape(title)} · Neural Mech</title><style>{CSS}</style></head><body>{nav()}{body}<footer class="site-footer"><div class="shell"><span>Neural Mech / Facility Systems</span><span>Registry ready for expansion</span></div></footer></body></html>'''.encode()

def assets_page():
    return page('Assets', f'''<main><section class="hero shell"><div><p class="eyebrow">Facility inventory / 01</p><h1>Assets</h1></div><div class="hero-copy"><p>Operational equipment, mapped into one precise view. Select an asset to inspect its digital twin.</p><div class="count"><span>Registered units</span><strong>01</strong></div></div></section><section class="registry shell"><div class="registry-head"><span>Active registry</span><span>1 result</span></div><a class="asset" href="/digital-twin/HVAC-001"><div class="asset-info"><span class="asset-kicker">Air systems / AHU</span><h2>HVAC-001</h2><span class="asset-type">Primary air handling unit</span><div class="facts"><div class="fact"><span>Location</span><strong>Plant Room · Level 01</strong></div><div class="fact"><span>Operating state</span><strong class="status">Nominal</strong></div></div></div><div class="asset-visual">{hvac()}</div></a></section></main>''')

def digital_twin_page(asset_id):
    sid = escape(asset_id)
    return page(f'Digital Twin — {asset_id}', f'''<main class="shell"><a class="back" href="/assets">← &nbsp; Asset registry</a><section class="detail-head"><div><p class="eyebrow">Digital twin / AHU</p><h1 class="detail-title">{sid}</h1></div><p class="detail-heading"><span>Integration state · 00</span>Digital twin<br>coming online</p></section><section class="twin-layout"><div class="twin-stage">{hvac(True)}</div><aside class="meta"><h2>Equipment record</h2><dl><div><dt>Status</dt><dd class="status">Nominal</dd></div><div><dt>Type</dt><dd>Air handling unit</dd></div><div><dt>Location</dt><dd>Plant Room / L01</dd></div><div><dt>Integration</dt><dd>Awaiting telemetry</dd></div></dl><div class="telemetry"><span class="micro">Future telemetry</span><div class="telemetry-row"><span>Supply air</span><i></i></div><div class="telemetry-row"><span>Fan speed</span><i></i></div><div class="telemetry-row"><span>Filter ΔP</span><i></i></div></div></aside></section></main>''')

class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        path = unquote(urlparse(self.path).path).rstrip('/') or '/'
        if path in {'/', '/home', '/assets'}: self.send_html(assets_page()); return
        if path.startswith('/digital-twin/'):
            self.send_html(digital_twin_page(path[len('/digital-twin/'):])) if path != '/digital-twin' else self.send_html(page('Not Found',''),404); return
        self.send_html(page('Not Found','<main class="shell notfound"><p class="eyebrow">Error / 404</p><h1>Page not found</h1><a class="back" href="/assets">← Asset registry</a></main>'),404)
    def send_html(self, body, status=200):
        self.send_response(status); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
    def log_message(self, format, *args): print(f'{self.address_string()} - {format % args}')

if __name__ == '__main__':
    server=ThreadingHTTPServer((HOST,PORT),RequestHandler); print(f'Serving on http://{HOST}:{PORT}')
    try: server.serve_forever()
    except KeyboardInterrupt: print('\nStopping server')
    finally: server.server_close()
